const rows = $input.all();
const state = $getWorkflowStaticData('global');
state.notified = state.notified || {};
const out = [];
for (const item of rows) {
  const j = item.json || {};
  const requestId = String(j.id || j['Request ID'] || '');
  if (!requestId || state.notified[requestId]) continue;
  state.notified[requestId] = Date.now();
  out.push({ json: {
    requestId,
    actionName: String(j['Action Name'] || 'Unnamed action'),
    actionPayload: String(j['Action Payload'] || ''),
    requestedBy: String(j['Requested By'] || ''),
    requestedAt: String(j['Requested At'] || ''),
    subject: 'Approval required: ' + String(j['Action Name'] || 'Unnamed action'),
    message: 'A risky automation action is waiting for human approval.\n\nRequest ID: ' + requestId + '\nAction: ' + String(j['Action Name'] || '') + '\nRequested by: ' + String(j['Requested By'] || '') + '\nRequested at: ' + String(j['Requested At'] || '') + '\n\nPayload:\n' + String(j['Action Payload'] || '') + '\n\nReview the record in Airtable and set Approval Status to Approved or Rejected. No external action is executed while status remains Pending.'
  }});
}
return out;

const rows = $input.all();
const state = $getWorkflowStaticData('global');
state.released = state.released || {};
const out = [];
for (const item of rows) {
  const j = item.json || {};
  const requestId = String(j.id || j['Request ID'] || '');
  if (!requestId || state.released[requestId]) continue;
  state.released[requestId] = Date.now();
  out.push({ json: {
    requestId,
    approvalStatus: 'Approved',
    actionName: String(j['Action Name'] || 'Unnamed action'),
    actionPayload: String(j['Action Payload'] || ''),
    approvedBy: String(j['Approved By'] || ''),
    approvedAt: String(j['Approved At'] || ''),
    releasedAt: new Date().toISOString(),
    note: 'Connect the real external action after this node. This request ID will be released only once by this workflow.'
  }});
}
return out;
